import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Abrir documentos citados no editor de minutas","description":"","frontmatter":{"title":"Abrir documentos citados no editor de minutas","id":"eproc-abrir-link-documento-minuta","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.12.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-abrir-link-documento-minuta"}]]},"headers":[],"relativePath":"funcionalidades/eproc-abrir-link-documento-minuta.md","filePath":"funcionalidades/eproc-abrir-link-documento-minuta.md"}'),t={name:"funcionalidades/eproc-abrir-link-documento-minuta.md"};function n(s,o,d,u,c,l){return e(),r("div",null,o[0]||(o[0]=[i('<h1 id="abrir-documentos-citados-no-editor-de-minutas" tabindex="-1">Abrir documentos citados no editor de minutas <a class="header-anchor" href="#abrir-documentos-citados-no-editor-de-minutas" aria-label="Permalink to &quot;Abrir documentos citados no editor de minutas&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No editor de minutas, os links para documentos do processo (como &quot;evento 1, INIC1&quot;) não abrem com um clique: o duplo clique mostra uma janelinha &quot;Link para documento de processo&quot;, e só o botão &quot;Abrir&quot; dela abre o documento. Com este recurso, basta passar o mouse sobre o link e clicar no botão de abrir que aparece logo abaixo dele.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, no editor de minutas (ao criar ou editar uma minuta).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a minuta para edição.</li><li>Passe o mouse sobre um link para documento do processo.</li><li>Clique no botão de abrir (seta saindo de um quadrado), logo abaixo do link. O documento abre.</li></ol><p>Para editar o texto ou a página do link, dê um duplo clique no link, como antes: a janelinha do eproc continua disponível.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>O botão usa a mesma função do &quot;Abrir&quot; do eproc, então o documento abre do mesmo jeito que pela janelinha, mas sem abri-la e sem alterar o link na minuta.</p>',12)]))}const b=a(t,[["render",n]]);export{p as __pageData,b as default};
